def regionalised_spatial_weighted_mean(
    ds, variable, lon_slice, lat_slice, log_transformed, vmin, vmax
):
    da = ds[variable]
    da = utils.regionalise(da, lon_slice=lon_slice, lat_slice=lat_slice)
    if vmin is not None:
        da = da.where(da > vmin)
    if vmax is not None:
        da = da.where(da < vmax)
